        { id: 2, type: 'multiple-choice', question: "'He might be studying' expresses:", options: ["Certainty", "A strong probability", "A possibility", "Impossibility"], correctIndex: 2, explanation: "'Might' expresses a possibility \u2014 the speaker is not sure but thinks it is possible." },
        { id: 3, type: 'multiple-choice', question: "Which modal shows the speaker is almost sure about something?", options: ["might", "could", "may", "must"], correctIndex: 3, explanation: "'He must be working on his history revision' \u2014 the speaker sees evidence and is almost certain." },
        { id: 4, type: 'multiple-choice', question: "'He could be in the garden' means:", options: ["It is certain", "It is impossible", "It is possible", "It is probable"], correctIndex: 2, explanation: "'Could' expresses a possibility \u2014 the speaker is guessing one of several possible situations." }
