        { id: 2, type: 'multiple-choice', question: "What is the correct tag pattern in 'You were wearing a blue dress, weren't you?'", options: ["Negative + positive", "Positive + positive", "Positive + negative", "Negative + negative"], correctIndex: 2, explanation: "The sentence 'You were' is positive, so the tag 'weren't you?' is negative." },
        { id: 3, type: 'multiple-choice', question: "Sevara says 'He hasn't changed much, has he?' The sentence is negative, so the tag is:", options: ["negative", "positive", "the same", "different auxiliary"], correctIndex: 1, explanation: "Negative sentence ('hasn't') requires a positive tag ('has he?')." },
        { id: 4, type: 'multiple-choice', question: "What tag is used with 'Let's exchange phone numbers'?", options: ["will you?", "don't we?", "shall we?", "won't we?"], correctIndex: 2, explanation: "'Let's' suggestions always take 'shall we?' as the question tag." },
        { id: 5, type: 'true-false', question: "Madina asks 'You're Aziz's sister, aren't you?' to check information.", answer: true, explanation: "Question tags are used to confirm or check information — this is their main function." },
        { id: 6, type: 'fill-blank', question: "You _____ wearing a blue dress, weren't you?", answer: "were", explanation: "Positive sentence 'You were' needs a negative tag 'weren't you?'" },
        { id: 7, type: 'matching', question: "Match each sentence with its correct question tag:", pairs: [{ left: "You're Madina", right: "aren't you?" }, { left: "He hasn't changed much", right: "has he?" }, { left: "He can cook it himself", right: "can't he?" }, { left: "Let's exchange numbers", right: "shall we?" }], explanation: "Positive sentences take negative tags; negative sentences take positive tags. 'Let's' takes 'shall we?'" },
        { id: 8, type: 'multiple-answer', question: "Which of the following tag questions appear in the conversation? Select all that apply:", options: ["aren't you?", "didn't she?", "won't you?", "isn't it?"], correctIndices: [0, 2], explanation: "The conversation uses 'aren't you?', 'weren't you?', 'don't you?', 'has he?', 'can't he?', 'won't you?', 'shall we?', and 'won't we?'" }
