        { id: 8, type: 'ordering', question: "Put the tourist's questions in the order they appear:", options: ["Ask about souvenirs", "Ask about the line to take", "Ask about Sunday opening hours", "Ask how to get to the bazaar"], correctOrder: [3, 1, 2, 0], explanation: "The tourist first asks about getting to the bazaar, then which line, then Sunday hours, then souvenirs." }
