        { id: 8, type: 'matching', question: "Match each nominalized phrase with its verb-based equivalent:", pairs: [{ left: "the transformation of social structures", right: "social structures were transformed" }, { left: "the separation of generations", right: "generations were separated" }, { left: "the concentration of educational resources", right: "educational resources were concentrated" }, { left: "the establishment of new universities", right: "new universities were established" }], explanation: "Nominalization converts verb actions into noun phrases for more formal academic expression." }
